/* every corner is square, only the turning loaders stay round */
:root:not([data-style="soft"]) *,:root:not([data-style="soft"]) *::before,:root:not([data-style="soft"]) *::after{border-radius:0!important}
:root:not([data-style="soft"]) .spin,:root:not([data-style="soft"]) .radar::before,:root:not([data-style="soft"]) .radar::after{border-radius:50%!important}
:root:not([data-style="soft"]) svg:not(.i):not(.brand) rect{rx:0;ry:0}
:root:not([data-style="soft"]) svg:not(.i):not(.brand) :is(path,line,polyline,circle){stroke-linecap:butt}
/* no blur anywhere: things wipe in or cut, they never soften */
:root:not([data-style="soft"]) *,:root:not([data-style="soft"]) *::before,:root:not([data-style="soft"]) *::after{filter:none!important}

/* the sheet: cards share their hairlines, every stage is drafting paper with crop marks in the corners */
:root:not([data-style="soft"]) .seg2 .knob{box-shadow:0 0 0 1px var(--rail)}

/* parts: mono labels, hairline controls, hatched when disabled */
:root:not([data-style="soft"]) .tag{font-family:var(--mono);font-size:10.5px;font-weight:500;letter-spacing:.03em;text-transform:uppercase;height:19px;padding:0 6px}
:root:not([data-style="soft"]) .kbd{box-shadow:inset 0 0 0 1px var(--line)}
:root:not([data-style="soft"]) .pill.line{box-shadow:inset 0 0 0 1px var(--rail)}
:root:not([data-style="soft"]) .pill.line:hover{background:var(--wash);box-shadow:inset 0 0 0 1px var(--faint)}
:root:not([data-style="soft"]) .pill:active,:root:not([data-style="soft"]) .ib:active{transform:translateY(1px)}
:root:not([data-style="soft"]) .pill:is(.accent,.ink,.soft,.line)[disabled]{background-image:repeating-linear-gradient(135deg,transparent 0 4px,var(--grid) 4px 5px)}
:root:not([data-style="soft"]) .chip.on{box-shadow:inset 0 0 0 1px var(--rail)}
:root:not([data-style="soft"]) .mcx-add{box-shadow:none;outline:1px dashed var(--rail);outline-offset:-1px}
:root:not([data-style="soft"]) .bub{background:var(--chip);box-shadow:inset 0 0 0 1px var(--line)}
:root:not([data-style="soft"]) .tip{box-shadow:none}

/* motion: a top-down wipe that settles on a hard ease, stepped loaders, a blinking cursor instead of a soft ping */
@keyframes bpin{0%{opacity:0;clip-path:inset(0 0 100% 0);transform:translateY(4px)}30%{opacity:1}100%{opacity:1;clip-path:inset(0 0 0 0);transform:none}}
@keyframes bpout{to{opacity:0;clip-path:inset(0 0 100% 0)}}
@keyframes bpblink{0%,55%{opacity:1}56%,100%{opacity:.2}}
:root:not([data-style="soft"]) .enter,:root:not([data-style="soft"]) .pop-in{animation-name:bpin;animation-duration:var(--t-slow);animation-timing-function:var(--ease);animation-fill-mode:backwards}
:root:not([data-style="soft"]) .leave{animation:bpout .26s var(--ease) both}
:root:not([data-style="soft"]) .chx-card.show{animation:bpin .34s var(--ease) backwards}
:root:not([data-style="soft"]) .sw.out{transform:translateY(-3px)}
:root:not([data-style="soft"]) .pop{transform:translateY(4px);transition-duration:.16s}
:root:not([data-style="soft"]) .pop.open{transform:none}
:root:not([data-style="soft"]) .spin{animation:rot .9s steps(8) infinite}
:root:not([data-style="soft"]) .radar::after{animation:rot 1s steps(8) infinite}
:root:not([data-style="soft"]) .pulse{animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .pulse::after{display:none}
:root:not([data-style="soft"]) .btx-ask::after{background:linear-gradient(90deg,transparent 0 40%,rgba(255,255,255,.38) 40% 46%,transparent 46%)}
:root:not([data-style="soft"]) .btx-ask:hover::after{transition:transform .5s steps(10)}
:root:not([data-style="soft"]) .btx-live::after{display:none}
:root:not([data-style="soft"]) .btx-live{animation:bpblink 1.1s steps(1,end) infinite}

/* a component card: the template renders into .stage-in */
[data-c]{width:440px;max-width:100%;font-family:var(--sans);font-size:14px;line-height:1.5;color:var(--fg);-webkit-font-smoothing:antialiased}
[data-c].wide{width:720px}

